SELECT start_date                   AS startDate,
       end_date                     AS endDate,
       content                      AS content,
       IF(checked = 1, TRUE, FALSE) AS completed
FROM planner
WHERE YEAR(start_date) = #{year}
  AND MONTH(start_date) = #{month}
  AND DAY(start_date) = #{day}
  AND user_id = #{userId}

